          "qt": "63 歳の女性。倦怠感を主訴に、夫とともに来院した。夫からみると「以前と比べて、ぼーっとしている」とのことであった。36 歳と57 歳でうつ病と診断されている。2 回とも抗うつ薬を服用し、6 か月程度で回復し、1 年ほど服薬を続けた。その後は抑うつ感を認めていない。うつ病の時期を除いて仕事は順調で、職場では事務能力を高く評価されていた。仕事は順調であったが、3 か月前、自分に合わない上司にかわったことを嘆いていた。2 か月前から「体がだるい。疲れやすい。頭痛がする」と訴えたため、自宅近くの診療所を受診し、抗不安薬と睡眠薬を処方された。<br/>薬物を増量しながら仕事を続けていたが、1 か月前から仕事のはかどりが著しく悪くなり、周囲からみてもぼーっとしている時間が長くなった。3 週前から仕事に行っても仕事にならないため自宅で休養しているという。本日受診時、<br/>ぼーっとした表情であり、少し暗い感じであった。改訂長谷川式簡易知能評価スケールは9 点（30 点満点）で、回答には非常に時間がかかった。<br/><strong>この時点で最も可能性の低い疾患</strong>はどれか。",
