          "qt": "38 歳の女性。四肢の脱力を主訴に来院した。5 か月前に特に誘因なく両下腿以遠にじんじんとしたしびれ感を自覚するようになったが、症状は変動があり、軽減することもあったため様子をみていた。2 か月前に両上肢にも同様の症状がみられるようになり、2 週間前から徐々に両上下肢の脱力が強くなり、つま先がひっかかって転倒したり、<br/>瓶の蓋が開けられなくなったりしたため受診した。意識は清明。体温36.0℃。脈拍64/ 分、整。血圧114/60mmHg。<br/>心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。四肢に浮腫や皮疹、剛毛を認めない。<br/>脳神経に異常を認めない。腱反射は四肢で消失。Babinski 徴候は陰性。徒手筋力テストは両上肢近位筋で4。握力は右8kg、左10kg。両下肢近位筋は4、前脛骨筋、下腿三頭筋は3 で、つま先立ちはかろうじて可能である。異常感覚の自覚はあるが、触覚、温痛覚は正常。振動覚は両上下肢とも低下している。尿所見および血液所見に異常を認めない。<br/>心電図と胸部エックス線写真に異常を認めない。脳脊髄液検査：初圧80mmH2O（基準70 ～170）、細胞数1/μL（基準0 ～2）、蛋白（定量）126mg/dL（基準15 ～45）、糖（定量）56mg/dL（基準50 ～75）。運動神経伝導検査の結果を示す。<br/>適切な治療はどれか。2 つ選べ。",
